insert into public.questions (id, category, text, answers, correct, explanation, source) values ('b7ff2df406', 'strony', 'Który znacznik HTML służy do tworzenia nagłówka najwyższego stopnia?', '["<h1>","<head>","<header>","<h6>"]'::jsonb, 0, '<h1> to najważniejszy nagłówek, <h6> najmniej ważny. <head> to sekcja metadanych dokumentu.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('861b250966', 'strony', 'Atrybut alt w znaczniku <img> określa', '["tekst alternatywny wyświetlany, gdy obraz się nie wczyta","wysokość obrazu","adres pliku graficznego","podpis pod obrazem widoczny zawsze"]'::jsonb, 0, 'alt opisuje obraz dla czytników ekranu i jest pokazywany, gdy grafika się nie załaduje.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('b2df5708b4', 'strony', 'Aby połączyć dwie komórki tabeli w poziomie, należy użyć atrybutu', '["colspan=\"2\"","rowspan=\"2\"","merge=\"2\"","span=\"row\""]'::jsonb, 0, 'colspan łączy kolumny (poziomo), rowspan łączy wiersze (pionowo).', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('06f5845db2', 'strony', 'Aby połączyć dwie komórki tabeli w pionie, należy użyć atrybutu', '["rowspan=\"2\"","colspan=\"2\"","valign=\"2\"","height=\"2\""]'::jsonb, 0, 'rowspan rozciąga komórkę na kilka wierszy.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('d858d7c2f7', 'strony', 'Który znacznik tworzy listę numerowaną?', '["<ol>","<ul>","<dl>","<li>"]'::jsonb, 0, 'ol = ordered list. ul to lista punktowana, li to pojedynczy element listy.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('c480efc3d4', 'strony', 'Link otwierający stronę w nowej karcie wymaga atrybutu', '["target=\"_blank\"","target=\"_self\"","rel=\"new\"","href=\"_new\""]'::jsonb, 0, '_blank otwiera nowe okno lub kartę, _self (domyślnie) tę samą.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('93dd59b7ee', 'strony', 'Który zapis tworzy odnośnik do kotwicy o id „kontakt” na tej samej stronie?', '["<a href=\"#kontakt\">","<a href=\"kontakt\">","<a name=\"#kontakt\">","<a id=\"kontakt\">"]'::jsonb, 0, 'Znak # w href wskazuje element o danym id w bieżącym dokumencie.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('a9effd9575', 'strony', 'Element formularza, który pozwala wybrać jedną opcję z rozwijanej listy, to', '["<select>","<input type=\"checkbox\">","<textarea>","<fieldset>"]'::jsonb, 0, '<select> z elementami <option> tworzy listę rozwijaną.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('d8ea886380', 'strony', 'Pola typu radio należą do jednej grupy, gdy mają ten sam atrybut', '["name","id","value","class"]'::jsonb, 0, 'Przeglądarka grupuje przyciski radio po wspólnej wartości name: można zaznaczyć tylko jeden z grupy.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('a048cdf2d7', 'strony', 'Kliknięcie etykiety ustawia kursor w polu tekstowym, jeżeli', '["atrybut for etykiety jest równy id pola","atrybut name etykiety jest równy name pola","etykieta ma klasę pola","pole ma atrybut label"]'::jsonb, 0, '<label for="x"> jest powiązany z elementem o id="x".', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('3dbb41fd35', 'strony', 'Metoda formularza, która przesyła dane widoczne w pasku adresu, to', '["GET","POST","PUT","SEND"]'::jsonb, 0, 'GET dokleja dane do URL jako query string; POST wysyła je w treści żądania.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('d19c05d778', 'strony', 'Znacznik <br> służy do', '["przejścia do nowej linii","pogrubienia tekstu","wstawienia poziomej linii","utworzenia akapitu"]'::jsonb, 0, '<br> to łamanie linii. Pozioma linia to <hr>, akapit to <p>.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('693f2ea003', 'strony', 'Który znacznik semantyczny HTML5 oznacza stopkę strony lub sekcji?', '["<footer>","<bottom>","<section>","<aside>"]'::jsonb, 0, '<footer> to stopka, <aside> to treść poboczna, <section> to sekcja tematyczna.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('adc71d0309', 'strony', 'Prawidłowa deklaracja typu dokumentu HTML5 to', '["<!DOCTYPE html>","<!DOCTYPE HTML5>","<html version=\"5\">","<?xml html?>"]'::jsonb, 0, 'W HTML5 deklaracja jest maksymalnie skrócona.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('88a4dcc375', 'strony', 'Kodowanie znaków UTF-8 ustawia się w HTML5 znacznikiem', '["<meta charset=\"UTF-8\">","<meta lang=\"UTF-8\">","<charset>UTF-8</charset>","<html encoding=\"UTF-8\">"]'::jsonb, 0, 'meta charset w sekcji head ustala kodowanie dokumentu, dzięki czemu polskie znaki wyświetlają się poprawnie.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('6911d10f74', 'strony', 'Arkusz stylów zewnętrzny dołącza się do dokumentu znacznikiem', '["<link rel=\"stylesheet\" href=\"styl.css\">","<style src=\"styl.css\">","<css href=\"styl.css\">","<script href=\"styl.css\">"]'::jsonb, 0, '<link> umieszczamy w head. <style> służy do stylów wewnętrznych.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('65e50f6ca1', 'strony', 'Selektor CSS #menu odnosi się do elementu', '["o id=\"menu\"","o class=\"menu\"","o nazwie znacznika menu","o atrybucie name=\"menu\""]'::jsonb, 0, '# to selektor identyfikatora, kropka to selektor klasy.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('85cfe14fe8', 'strony', 'Selektor CSS .ramka odnosi się do elementów', '["z klasą ramka","o id ramka","znacznika <ramka>","wewnątrz elementu ramka"]'::jsonb, 0, 'Kropka oznacza klasę; jeden element może mieć wiele klas.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('13831400df', 'strony', 'Pseudoklasa, która formatuje element po najechaniu kursorem, to', '[":hover",":active",":focus",":visited"]'::jsonb, 0, ':hover działa przy najechaniu myszą, :active w chwili kliknięcia, :visited dla odwiedzonych linków.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('010c467090', 'strony', 'Pseudoklasa :nth-child(odd) wybiera', '["elementy nieparzyste","elementy parzyste","tylko pierwszy element","ostatni element"]'::jsonb, 0, 'odd = nieparzyste (1, 3, 5…), even = parzyste. Często używane do „pasków” w tabelach.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('ce91faa439', 'strony', 'Pseudoelement ::first-letter pozwala sformatować', '["pierwszą literę tekstu w elemencie","pierwszy wiersz tekstu","pierwszy element potomny","pierwsze słowo w akapicie"]'::jsonb, 0, 'Do pierwszego wiersza służy ::first-line.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('260221dff0', 'strony', 'Właściwość CSS ustalająca kolor tekstu to', '["color","font-color","text-color","foreground"]'::jsonb, 0, 'Tło ustawia background-color, tekst po prostu color.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('2ef4f9bd11', 'strony', 'Która właściwość CSS ustawia odstęp WEWNĄTRZ ramki elementu (między treścią a obramowaniem)?', '["padding","margin","border-spacing","gap"]'::jsonb, 0, 'padding to margines wewnętrzny, margin to margines zewnętrzny.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('d10337b1b6', 'strony', 'Zapis margin: 10px 20px; oznacza', '["10px góra i dół, 20px lewo i prawo","10px lewo i prawo, 20px góra i dół","10px góra, 20px dół","10px ze wszystkich stron i 20px odstępu"]'::jsonb, 0, 'Dwie wartości: pierwsza pionowo (góra, dół), druga poziomo (prawo, lewo).', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('94d16eef62', 'strony', 'Aby wyśrodkować blok o ustalonej szerokości w poziomie, stosuje się', '["margin: 0 auto;","text-align: center;","align: center;","float: center;"]'::jsonb, 0, 'Automatyczne marginesy boczne dzielą wolne miejsce po równo. text-align centruje treść liniową, nie blok.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('5274b46d1d', 'strony', 'Właściwość float: left powoduje', '["opływanie elementu przez treść i przesunięcie go do lewej","ukrycie elementu","przyklejenie elementu do lewej krawędzi okna","pozycjonowanie absolutne"]'::jsonb, 0, 'Float był klasyczną techniką układów kolumnowych w arkuszach egzaminacyjnych. clear: both kończy opływanie.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('92984b5744', 'strony', 'Właściwość clear: both stosuje się, aby', '["element nie był opływany z żadnej strony","usunąć wszystkie style","wyczyścić tło","usunąć marginesy"]'::jsonb, 0, 'Typowo dla stopki pod kolumnami ustawionymi przez float.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('57e48fcfb2', 'strony', 'Która wartość display ukrywa element tak, że nie zajmuje on miejsca na stronie?', '["none","hidden","invisible","collapse-all"]'::jsonb, 0, 'visibility: hidden ukrywa, ale zostawia puste miejsce; display: none całkowicie usuwa z układu.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('3d68c56480', 'strony', 'Właściwość CSS ustawiająca zaokrąglenie narożników to', '["border-radius","corner-radius","border-round","radius"]'::jsonb, 0, 'Np. border-radius: 10px; lub 50% dla koła.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('bded88e4c6', 'strony', 'Cień pod blokiem uzyskuje się właściwością', '["box-shadow","text-shadow","shadow","filter: shadow"]'::jsonb, 0, 'text-shadow dotyczy tekstu, box-shadow całego pudełka.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('49f71621e6', 'strony', 'Właściwość transition w CSS służy do', '["płynnej zmiany wartości właściwości w czasie","przenoszenia elementu do innego rodzica","zmiany kolejności elementów","tłumaczenia tekstu"]'::jsonb, 0, 'np. transition: background-color 0.5s; zmienia kolor płynnie przy :hover.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('337bc85e20', 'strony', 'Reguła @media (max-width: 600px) { … } zostanie zastosowana, gdy', '["szerokość okna wynosi co najwyżej 600px","szerokość okna wynosi co najmniej 600px","drukujemy dokument","ekran ma 600 dpi"]'::jsonb, 0, 'max-width = do 600px włącznie; to podstawa responsywności.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('0d019fe5ba', 'strony', 'Jednostka rem w CSS odnosi się do', '["rozmiaru czcionki elementu głównego (html)","rozmiaru czcionki rodzica","szerokości okna","wysokości okna"]'::jsonb, 0, 'em zależy od rodzica, rem od elementu root. vw/vh to procent okna.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('42bf807120', 'strony', 'Kolor #FF0000 w zapisie szesnastkowym to', '["czerwony","zielony","niebieski","biały"]'::jsonb, 0, 'Kolejne pary to R, G, B. FF w kanale R i 00 w pozostałych daje czysty czerwony.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('8db5173aad', 'strony', 'Zapis rgba(0, 0, 0, 0.5) oznacza', '["czarny z przezroczystością 50%","biały z przezroczystością 50%","szary bez przezroczystości","kolor niepoprawny"]'::jsonb, 0, 'Czwarty parametr alfa: 0 = przezroczysty, 1 = pełny.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('57383a176b', 'strony', 'Właściwość list-style-type: square ustawia', '["punktor w kształcie kwadratu","numerację rzymską","brak punktora","listę w poziomie"]'::jsonb, 0, 'Inne: disc, circle, none, decimal, upper-roman.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('101dadbf08', 'strony', 'Aby tabela miała pojedyncze linie obramowania zamiast podwójnych, należy użyć', '["border-collapse: collapse;","border-style: single;","border-spacing: 2;","table-border: 1;"]'::jsonb, 0, 'collapse scala sąsiednie ramki komórek w jedną.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('74a4590358', 'strony', 'Która metoda JavaScript zwraca element o podanym identyfikatorze?', '["document.getElementById()","document.getElementsByName()","document.querySelectorAll()","document.getId()"]'::jsonb, 0, 'getElementById zwraca jeden element albo null.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('94bb425ff1', 'strony', 'Właściwość innerHTML pozwala', '["odczytać lub zmienić zawartość HTML elementu","zmienić styl elementu","usunąć element","pobrać wartość pola formularza zawsze jako liczbę"]'::jsonb, 0, 'innerHTML interpretuje znaczniki, textContent wstawia czysty tekst.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('00249dea5c', 'strony', 'Wartość wpisaną w polu <input> w JavaScript odczytuje się przez właściwość', '["value","text","innerText","content"]'::jsonb, 0, 'Wynik zawsze jest typu string; do liczb trzeba użyć Number() lub parseInt().', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('2d54563e37', 'strony', 'Funkcja parseInt("12abc") w JavaScript zwróci', '["12","NaN","\"12abc\"","0"]'::jsonb, 0, 'parseInt czyta cyfry od początku i zatrzymuje się na pierwszym znaku niebędącym cyfrą.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('4767bdeadf', 'strony', 'Wynik wyrażenia "5" + 3 w JavaScript to', '["\"53\"","8","NaN","błąd"]'::jsonb, 0, 'Operator + z napisem skleja tekst. Natomiast "5" * 3 da 15.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('a761df4f6e', 'strony', 'Operator === w JavaScript porównuje', '["wartość i typ","tylko wartość","tylko typ","adresy w pamięci zmiennych prostych"]'::jsonb, 0, '5 == "5" to true, ale 5 === "5" to false.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('d57f3ab820', 'strony', 'Zdarzenie wywoływane po kliknięciu elementu to', '["onclick","onchange","onload","onmouseover"]'::jsonb, 0, 'onmouseover reaguje na najechanie, onchange na zmianę wartości pola.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('ed68d2410e', 'strony', 'Aby zmienić kolor tła elementu el na czerwony w JS, piszemy', '["el.style.backgroundColor = \"red\";","el.style.background-color = \"red\";","el.css(\"background\", \"red\");","el.color = \"red\";"]'::jsonb, 0, 'W JS nazwy właściwości CSS z myślnikiem zapisuje się camelCase.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('4aa261f9e1', 'strony', 'Metoda tworząca nowy element HTML w JavaScript to', '["document.createElement()","document.newElement()","document.appendChild()","document.addElement()"]'::jsonb, 0, 'Po utworzeniu element dołącza się do drzewa przez appendChild() lub append().', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('5b266de08a', 'strony', 'Pętla for (let i = 0; i < 5; i++) wykona się', '["5 razy","4 razy","6 razy","w nieskończoność"]'::jsonb, 0, 'i przyjmuje wartości 0, 1, 2, 3, 4.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('8fd2686358', 'strony', 'Funkcja Math.random() w JavaScript zwraca', '["liczbę z przedziału [0, 1)","liczbę całkowitą 0–100","losowy element tablicy","liczbę z przedziału [1, 10]"]'::jsonb, 0, 'Losową liczbę całkowitą od 1 do 6: Math.floor(Math.random() * 6) + 1.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('0c268c5416', 'strony', 'Do trwałego zapisu danych w przeglądarce (bez daty wygaśnięcia) służy', '["localStorage","sessionStorage","window.name","document.title"]'::jsonb, 0, 'sessionStorage znika po zamknięciu karty.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('e35a7cc996', 'strony', 'Walidator W3C służy do', '["sprawdzania poprawności kodu HTML/CSS","kompresji obrazów","testowania wydajności serwera","szyfrowania strony"]'::jsonb, 0, 'validator.w3.org sprawdza zgodność ze standardem.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('ed50a697d5', 'bazy', 'Klauzula SQL służąca do filtrowania wierszy przed grupowaniem to', '["WHERE","HAVING","ORDER BY","GROUP BY"]'::jsonb, 0, 'WHERE filtruje wiersze, HAVING filtruje grupy po GROUP BY.', 'original');
