insert into public.questions (id, category, text, answers, correct, explanation, source) values ('1e4a6a3d14', 'bazy', 'Operator BETWEEN 10 AND 20 w SQL', '["obejmuje wartości 10 i 20","wyklucza obie granice","obejmuje tylko 10","obejmuje tylko 20"]'::jsonb, 0, 'BETWEEN jest domknięty z obu stron.', 'original');
insert into public.questions (id, category, text, answers, correct, explanation, source) values ('a3fcf17df5', 'bazy', 'Aby sprawdzić, czy pole jest puste (brak wartości), w SQL stosuje się', '["IS NULL","= NULL","== NULL","EMPTY()"]'::jsonb, 0, 'Porównanie = NULL zawsze daje nieznany wynik; używaj IS NULL / IS NOT NULL.', 'original');
