insert into public.questions (id, category, text, answers, correct, explanation, source) values ('1eb5cc51e7', 'bazy', 'Polecenie modyfikujące istniejące rekordy to', '["UPDATE … SET …","ALTER … SET …","MODIFY …","INSERT … SET …"]'::jsonb, 0, 'Bez WHERE UPDATE zmieni wszystkie wiersze tabeli.', 'original');
