insert into public.questions (id, category, text, answers, correct, explanation, source) values ('9af3af0d68', 'bazy', 'Relacja wiele do wielu (n:m) w relacyjnej bazie danych jest realizowana przez', '["tabelę pośredniczącą z dwoma kluczami obcymi","jeden klucz obcy w każdej tabeli","kolumnę z listą wartości","widok"]'::jsonb, 0, 'Np. tabela zapisy(uczen_id, kurs_id) łączy uczniów i kursy.', 'original');
