insert into public.flashcards (id, deck, front, back, example) values ('html-0', 'html', '<table>, <tr>, <th>, <td>', 'Tabela, wiersz, komórka nagłówkowa, komórka danych', '<table><tr><th>Imię</th></tr><tr><td>Ala</td></tr></table>');
